  releaseOptionMarks(sel);releaseGuardDisabled(sel);restoreDash(sel);
  if(chooseFirst&&!sel.value){const first=[...sel.options].find(o=>o.value&&!o.disabled);if(first)sel.value=first.value;}
  delete sel.dataset.gra415Unavailable;
  if(had)setDirty(section);
